-- Synthetic evidence metadata only. Entire suite rolls back; no fictitious badge persists.
begin;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
create function pg_temp.denied(q text) returns void language plpgsql as $$begin begin execute q;exception when insufficient_privilege or check_violation or raise_exception or serialization_failure or not_null_violation then return;end;raise exception 'UNEXPECTEDLY ALLOWED: %',q;end$$;
