set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000001","role":"authenticated"}';set local role authenticated;
insert into fixture(a,v) select (d->'application'->>'id')::uuid,1 from public.verification_start() d;
select pg_temp.ok((public.verification_state()->'current'->'application'->>'status')='draft','draft resume');
