select pg_temp.denied(format('select public.verification_save_step(%L,1,''bank'',''{"role":"super_admin"}'')',a)) from fixture;
select public.verification_save_step(a,v,'identity','{"legal_name":"Synthetic Owner","dob":"1990-01-01","address":"Synthetic address","document_number":"0012345","no_expiry":true}') is not null from fixture;update fixture set v=v+1;
select public.verification_save_step(a,v,'trade_license',jsonb_build_object('license_number','000123','business_name','Synthetic verification business','owner_name','Synthetic Owner','issuing_authority','Synthetic authority','business_address','Synthetic address','issued_on','2025-01-01','expires_on',(now() at time zone 'Asia/Dhaka')::date+30)) is not null from fixture;update fixture set v=v+1;
select public.verification_save_step(a,v,'bank','{"bank_name":"Synthetic bank","branch_name":"Synthetic branch","account_title":"Synthetic Owner","account_number":"0000123456","holder_type":"owner"}') is not null from fixture;update fixture set v=v+1;
reset role;
