set local role authenticated;
select public.verification_attach_file(a,v,'identity_front','b1000000-0000-4000-8000-000000000001/'||a||'/identity_front/00000000-0000-4000-8000-000000000001.jpg') is not null from fixture;update fixture set v=v+1;
select public.verification_attach_file(a,v,'trade_license','b1000000-0000-4000-8000-000000000001/'||a||'/trade_license/00000000-0000-4000-8000-000000000001.jpg') is not null from fixture;update fixture set v=v+1;
