select public.verification_submit(a,v,true) is not null from fixture;update fixture set v=v+1;
select pg_temp.denied(format('select public.verification_save_step(%L,%s,''bank'',''{}'')',a,v)) from fixture;
select pg_temp.denied($$update public.verification_bank set account_number='tampered'$$);
