select pg_temp.ok((select count(*)=0 from public.verification_files),'staff file RLS');
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='business-documents' and name like 'b1000000%'),'staff storage denied');
select pg_temp.denied(format('select public.verification_get(%L)',a)) from fixture;
select pg_temp.denied(format('select public.verification_decide(%L,%s,''{}'')',a,v)) from fixture;
select pg_temp.ok((select count(*)=0 from public.admin_audit_logs where action like 'verification.%'),'staff audit privacy');
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000004","role":"authenticated"}';
select pg_temp.denied(format('select public.verification_get(%L)',a)) from fixture;
