select public.verification_decide(a,v,'{"decision":"approved","holder_match_confirmed":true,"sections":{"identity":{"status":"approved","note":""},"trade_license":{"status":"approved","note":""},"bank":{"status":"approved","note":""}}}') is not null from fixture;update fixture set v=v+1;
