update fixture set old=a;update fixture set a=(public.verification_start()->'application'->>'id')::uuid,v=1;
select pg_temp.ok(private.supplier_verified('b2000000-0000-4000-8000-000000000001'),'renewal draft preserves badge');
select pg_temp.denied($$update public.businesses set verification_application_id=null where owner_id=auth.uid()$$);
select public.verification_submit(a,v,true) is not null from fixture;update fixture set v=v+1;
select pg_temp.ok(not private.supplier_verified('b2000000-0000-4000-8000-000000000001'),'replacement submission pauses badge');
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated"}';
select public.verification_decide(a,v,'{"decision":"approved","holder_match_confirmed":true,"sections":{"identity":{"status":"approved","note":""},"trade_license":{"status":"approved","note":""},"bank":{"status":"approved","note":""}}}') is not null from fixture;
select pg_temp.denied(format('select public.verification_decide(%L,10,''{"decision":"revoked","reason":"Superseded application"}'')',old)) from fixture;
reset role;
update public.verification_applications set valid_until=(now() at time zone 'Asia/Dhaka')::date+1 where id=(select old from fixture);
select private.reconcile_supplier_verifications();
select pg_temp.ok(not exists(select 1 from private.verification_notices where application_id=(select old from fixture) and event='renewal_due'),'superseded revision does not send renewal notice');
