select public.admin_set_account_status('b1000000-0000-4000-8000-000000000001','active','Synthetic reactivation');
reset role;
update public.verification_applications set valid_until=(now() at time zone 'Asia/Dhaka')::date-1 where id=(select a from fixture);
select pg_temp.ok(not private.supplier_verified('b2000000-0000-4000-8000-000000000001'),'expiry effective before cron');
select private.reconcile_supplier_verifications();select private.reconcile_supplier_verifications();
select pg_temp.ok((select status='expired' from public.verification_applications where id=(select a from fixture)),'cron reconciles expiry');
select pg_temp.ok((select count(*)=1 from public.verification_reviews where application_id=(select a from fixture) and decision='expired'),'cron idempotent');
